{
  "findings": [
    {
      "ref": "[D519]",
      "area": "contact",
      "claim": "A parent reports that online multiplayer games allow kids to chat with friends and strangers.",
      "stance": "risk",
      "quote": "Online multiplayer games allow kids to chat with friends and strangers."
    },
    {
      "ref": "[D519]",
      "area": "contact",
      "claim": "A parent reports that predators build trust by connecting with kids through games and then move them to less moderated apps.",
      "stance": "risk",
      "quote": "Predators build trust by connecting with kids through games, and then move kids to less moderated apps."
    },
    {
      "ref": "[D519]",
      "area": "contact",
      "claim": "A parent reports that grooming can escalate to sextortion where predators pressure kids into sharing personal information or explicit images.",
      "stance": "risk",
      "quote": "This tactic, known as grooming, is designed to isolate young users from trusted adults."
    },
    {
      "ref": "[D519]",
      "area": "money",
      "claim": "A parent reports that gaming platforms have virtual currencies with actual cash value that attract criminals.",
      "stance": "risk",
      "quote": "Gaming platforms have created their own economies using virtual currencies like V-Bucks (Fortnite), Robux (Roblox), and Minecoins (Minecraft). While these might seem like play money to kids, they have actual cash value and attract sophisticated criminals."
    },
    {
      "ref": "[D519]",
      "area": "money",
      "claim": "A parent reports that hackers make unauthorized purchases with saved payment methods after gaining account access.",
      "stance": "risk",
      "quote": "Once hackers gain access to an account, they typically follow a common pattern to profit from this theft. They usually start by making unauthorized purchases with any payment methods saved to the account."
    },
    {
      "ref": "[D519]",
      "area": "money",
      "claim": "A parent reports that stolen virtual items are transferred to other accounts and converted to real money on third-party marketplaces.",
      "stance": "risk",
      "quote": "The criminals then convert these stolen goods into real money by selling virtual items or entire compromised accounts on third-party marketplaces."
    },
    {
      "ref": "[D519]",
      "area": "data",
      "claim": "A parent reports that malware can steal passwords, payment information, and personal data from computers.",
      "stance": "risk",
      "quote": "These malicious programs are designed to steal passwords, payment information, and personal data, often targeting more than just gaming accounts."
    },
    {
      "ref": "[D519]",
      "area": "data",
      "claim": "A parent reports that malware can secretly track everything typed on the keyboard, record the screen, and access the device's camera.",
      "stance": "risk",
      "quote": "Once installed, this malware could secretly track everything typed on the keyboard, record the screen, and access the device's camera."
    },
    {
      "ref": "[D519]",
      "area": "data",
      "claim": "A parent reports that malware can mimic official Google and Facebook apps to deceive users into revealing passwords.",
      "stance": "risk",
      "quote": "It could even mimic official Google and Facebook apps to deceive users into revealing their passwords."
    },
    {
      "ref": "[D519]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate in online games does not reliably prevent children from interacting with predators.",
      "stance": "risk",
      "quote": "The anonymity of gaming platforms makes it easier for predators to blend in. And because these conversations often happen outside of parental supervision, kids may not recognize red flags until they're already in a dangerous situation."
    },
    {
      "ref": "[D519]",
      "area": "content",
      "claim": "A parent reports that fake sites or apps claim to offer free or heavily discounted in-game rewards to steal account information.",
      "stance": "risk",
      "quote": "For example, scammers create fake sites or apps that claim to offer free or heavily discounted V-Bucks, Robux, or other gaming currencies."
    },
    {
      "ref": "[D519]",
      "area": "developer_record",
      "claim": "A parent reports that cybercriminals have used malware like SpyNote to target players of a popular game by disguising it as a game mod.",
      "stance": "risk",
      "quote": "In 2023, hackers used a type of malware called SpyNote to target Roblox players by disguising it as a game mod."
    }
  ]
}
